contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try calling getTokens with an arbitrary payable amount
    function run(uint256 weiAmount) public payable {
        // must hold Ether if we will forward it
        if (weiAmount > 0) require(address(this).balance >= weiAmount);

        // read observables before the state-changing call
        uint256 before_totalDistributed = c.totalDistributed();
        uint256 before_totalRemaining = c.totalRemaining();
        uint256 before_balance = c.balanceOf(address(this));
        bool reverted;

        // perform the call and capture revert
        try c.getTokens{value: weiAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint256 after_totalDistributed = c.totalDistributed();
        uint256 after_totalRemaining = c.totalRemaining();
        uint256 after_balance = c.balanceOf(address(this));
        bool isBlacklisted = c.blacklist(address(this));

        // General property:
        // If the call succeeded then:
        //  - after_balance == before_balance + delta
        //  - after_totalDistributed == before_totalDistributed + delta
        //  - delta <= before_totalRemaining
        //  - the caller is blacklisted when delta > 0
        // If the call reverted then no observable changes occurred (conservative: totals unchanged and not blacklisted)
        uint256 delta_bal = after_balance - before_balance;
        uint256 delta_td = after_totalDistributed - before_totalDistributed;

        assert(
            // either reverted and nothing changed
            (reverted && after_totalDistributed == before_totalDistributed && after_totalRemaining == before_totalRemaining && after_balance == before_balance && isBlacklisted == false)
            ||
            // or succeeded and totals/balance increased consistently by same amount, bounded by previous remaining, and blacklisted iff given tokens > 0
            (!reverted && delta_bal == delta_td && delta_bal <= before_totalRemaining && after_totalRemaining + delta_td == before_totalRemaining && (delta_bal > 0 ? isBlacklisted == true : isBlacklisted == false))
        );
    }

    // receive so this contract can hold/send Ether
    receive() external payable {}
}

